using DomainRelay.Abstractions; using DriveOS.Application.Abstractions.Authentication; using DriveOS.Modules.Workforce.Application.PerformanceReviews; using DriveOS.Modules.Workforce.Domain.PerformanceReviews; using DriveOS.SharedKernel.Identifiers; using DriveOS.SharedKernel.Results;
namespace DriveOS.Api.Endpoints.Workforce;
internal static class PerformanceReviewEndpoints{internal static IEndpointRouteBuilder MapPerformanceReviewEndpoints(this IEndpointRouteBuilder app){var g=app.MapGroup("/api/workforce/performance-reviews").WithTags("Workforce - Performance Reviews");g.MapGet("/",List).RequireAuthorization("Workforce.PerformanceReviews.Read");g.MapGet("/{id:guid}",Get).RequireAuthorization("Workforce.PerformanceReviews.Read");g.MapPost("/",Create).RequireAuthorization("Workforce.PerformanceReviews.Manage");g.MapPost("/{id:guid}/start",Start).RequireAuthorization("Workforce.PerformanceReviews.Manage");g.MapPost("/{id:guid}/criteria",AddCriterion).RequireAuthorization("Workforce.PerformanceReviews.Manage");g.MapPut("/{id:guid}/criteria/{criterionId:guid}",RateCriterion).RequireAuthorization("Workforce.PerformanceReviews.Manage");g.MapPut("/{id:guid}/summary",Summary).RequireAuthorization("Workforce.PerformanceReviews.Manage");g.MapPost("/{id:guid}/submit",Submit).RequireAuthorization("Workforce.PerformanceReviews.Manage");g.MapPost("/{id:guid}/acknowledge",Acknowledge).RequireAuthorization("Workforce.PerformanceReviews.Acknowledge");g.MapPost("/{id:guid}/complete",Complete).RequireAuthorization("Workforce.PerformanceReviews.Validate");g.MapPost("/{id:guid}/cancel",Cancel).RequireAuthorization("Workforce.PerformanceReviews.Manage");return app;}
static async Task<IResult> List(Guid? employeeId,PerformanceReviewStatus? status,IMediator m,ICurrentTenant t,CancellationToken ct){if(t.OrganizationId is not{}o)return Results.Unauthorized();var r=await m.Send(new GetPerformanceReviewsQuery(o,employeeId.HasValue?new EmployeeId(employeeId.Value):null,status),ct);return r.IsSuccess?Results.Ok(r.Value):P(r.Error);}static async Task<IResult> Get(Guid id,IMediator m,ICurrentTenant t,CancellationToken ct){if(t.OrganizationId is not{}o)return Results.Unauthorized();var r=await m.Send(new GetPerformanceReviewQuery(o,new(id)),ct);return r.IsSuccess?Results.Ok(r.Value):P(r.Error);}static async Task<IResult> Create(CreateReviewRequest q,IMediator m,ICurrentTenant t,ICurrentUser u,CancellationToken ct){if(t.OrganizationId is not{}o||u.UserId is not{}a)return Results.Unauthorized();var id=PerformanceReviewId.New();var r=await m.Send(new CreatePerformanceReviewCommand(o,id,new(q.EmployeeId),new(q.EvaluatorUserId),q.PeriodFrom,q.PeriodTo,q.Title,a),ct);return r.IsSuccess?Results.Created($"/api/workforce/performance-reviews/{id.Value}",new{id=id.Value}):P(r.Error);}static Task<IResult> Start(Guid id,IMediator m,ICurrentTenant t,ICurrentUser u,CancellationToken ct)=>Send(id,m,t,u,(o,x,a)=>new StartPerformanceReviewCommand(o,x,a),ct);static async Task<IResult> AddCriterion(Guid id,CriterionRequest q,IMediator m,ICurrentTenant t,ICurrentUser u,CancellationToken ct){if(t.OrganizationId is not{}o||u.UserId is not{}a)return Results.Unauthorized();var cid=PerformanceReviewCriterionId.New();var r=await m.Send(new AddPerformanceReviewCriterionCommand(o,new(id),cid,q.Code,q.Label,q.Weight,q.Comment,a),ct);return r.IsSuccess?Results.Ok(new{id=cid.Value}):P(r.Error);}static async Task<IResult> RateCriterion(Guid id,Guid criterionId,RateCriterionRequest q,IMediator m,ICurrentTenant t,ICurrentUser u,CancellationToken ct){if(t.OrganizationId is not{}o||u.UserId is not{}a)return Results.Unauthorized();var r=await m.Send(new RatePerformanceReviewCriterionCommand(o,new(id),new(criterionId),q.Rating,q.Comment,a),ct);return r.IsSuccess?Results.NoContent():P(r.Error);}static async Task<IResult> Summary(Guid id,SummaryRequest q,IMediator m,ICurrentTenant t,ICurrentUser u,CancellationToken ct){if(t.OrganizationId is not{}o||u.UserId is not{}a)return Results.Unauthorized();var r=await m.Send(new SetPerformanceReviewSummaryCommand(o,new(id),q.OverallAssessment,q.Objectives,a),ct);return r.IsSuccess?Results.NoContent():P(r.Error);}static Task<IResult> Submit(Guid id,IMediator m,ICurrentTenant t,ICurrentUser u,CancellationToken ct)=>Send(id,m,t,u,(o,x,a)=>new SubmitPerformanceReviewCommand(o,x,a),ct);static async Task<IResult> Acknowledge(Guid id,AcknowledgeRequest q,IMediator m,ICurrentTenant t,ICurrentUser u,CancellationToken ct){if(t.OrganizationId is not{}o||u.UserId is not{}a)return Results.Unauthorized();var r=await m.Send(new AcknowledgePerformanceReviewCommand(o,new(id),q.EmployeeComment,a),ct);return r.IsSuccess?Results.NoContent():P(r.Error);}static Task<IResult> Complete(Guid id,IMediator m,ICurrentTenant t,ICurrentUser u,CancellationToken ct)=>Send(id,m,t,u,(o,x,a)=>new CompletePerformanceReviewCommand(o,x,a),ct);static async Task<IResult> Cancel(Guid id,CancelRequest q,IMediator m,ICurrentTenant t,ICurrentUser u,CancellationToken ct){if(t.OrganizationId is not{}o||u.UserId is not{}a)return Results.Unauthorized();var r=await m.Send(new CancelPerformanceReviewCommand(o,new(id),q.Reason,a),ct);return r.IsSuccess?Results.NoContent():P(r.Error);}static async Task<IResult> Send<T>(Guid id,IMediator m,ICurrentTenant t,ICurrentUser u,Func<OrganizationId,PerformanceReviewId,UserId,T> f,CancellationToken ct) where T:DriveOS.Application.Abstractions.Messaging.ICommand{if(t.OrganizationId is not{}o||u.UserId is not{}a)return Results.Unauthorized();var r=await m.Send(f(o,new(id),a),ct);return r.IsSuccess?Results.NoContent():P(r.Error);}static IResult P(Error e)=>Results.Problem(statusCode:e.Type switch{ErrorType.NotFound=>404,ErrorType.Conflict=>409,ErrorType.Validation=>400,_=>400},extensions:new Dictionary<string,object?>{{"code",e.Code},{"messageKey",e.MessageKey}});}
public sealed record CreateReviewRequest(Guid EmployeeId,Guid EvaluatorUserId,DateOnly PeriodFrom,DateOnly PeriodTo,string Title);public sealed record CriterionRequest(string Code,string Label,int Weight,string? Comment);public sealed record RateCriterionRequest(int Rating,string? Comment);public sealed record SummaryRequest(string OverallAssessment,string? Objectives);public sealed record AcknowledgeRequest(string? EmployeeComment);public sealed record CancelRequest(string Reason);
